/* Document queue and exact-source review presentation. Local synthetic data only. */
let documentQuery='',documentPatient='all',documentTemplate='all';
let reviewQuery='',reviewPatient='all',reviewKind='all',pendingDocumentReplacement=null;
const documentTemplates={soap:'SOAP consultation note',referral:'Referral letter',summary:'Patient-friendly summary',mdt:'MDT handover'};
function documentTitle(type){return documentTemplates[type]||'Clinical document';}
function filteredDocuments(){const q=documentQuery.trim().toLowerCase();return allDocumentRows().filter(({patient:p,record:r})=>(documentFilter==='all'||(documentFilter==='signed'?r.signed:!r.signed))&&(documentPatient==='all'||documentPatient===p.id)&&(documentTemplate==='all'||documentTemplate===r.noteTemplate)&&(!q||[p.name,p.id,documentTitle(r.noteTemplate)].join(' ').toLowerCase().includes(q)));}
function resetDocumentFilters(){documentQuery='';documentPatient='all';documentTemplate='all';documentFilter='all';render();}
function updateDocumentSearch(value){documentQuery=value;document.getElementById('document-queue-results').innerHTML=documentQueueRows();}
function documentQueueRows(){const rows=filteredDocuments();return `<div class="panel-head"><h2>${rows.length} ${rows.length===1?'document':'documents'}</h2><span class="fine">Current version per patient</span></div>${rows.length?rows.map(({patient:p,record:r})=>`<article class="document-queue-row"><span class="document-symbol">${icon('file')}</span><div class="document-queue-body"><button class="document-name" onclick="openPatient('${p.id}','N')">${esc(documentTitle(r.noteTemplate))}</button><p><strong>${esc(p.name)}</strong> · ${esc(p.id)}</p><div class="document-row-meta"><span>Version ${r.version}</span><span>${r.history.length} retained ${r.history.length===1?'copy':'copies'}</span><span class="pill ${r.signed?'green':'amber'}">${r.signed?'Reviewed locally':'Draft · Review required'}</span></div></div><div class="document-queue-actions"><button onclick="previewWorkspaceDocument('${p.id}')">Preview</button><button class="primary" onclick="${r.signed?`openPatient('${p.id}','N')`:`openDocumentForReview('${p.id}')`}">${r.signed?'Open document':'Review document'} ${icon('arrow')}</button></div></article>`).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('file')}</span><h3>${allDocumentRows().length?'No documents match':'No documents started'}</h3><p>${allDocumentRows().length?'Change the search, patient, template or review status.':'Choose a patient to start a note, referral letter or summary.'}</p><button onclick="${allDocumentRows().length?'resetDocumentFilters()':"chooseConsultation('N')"}">${allDocumentRows().length?'Clear filters':'Choose a patient'}</button></div>`}`;}
documentsPage=function(){const all=allDocumentRows(),reviewed=all.filter(x=>x.record.signed).length;return pageHeading('Documents','Find the current draft, check its source and retain reviewed versions.',`<button onclick="nav('review')">Open review queue</button><button class="primary" onclick="chooseConsultation('N')">${icon('plus')} Start document</button>`)+`<div class="document-queue-summary"><div><strong>${all.length}</strong><span>Current documents</span></div><div><strong>${all.length-reviewed}</strong><span>Awaiting review</span></div><div><strong>${reviewed}</strong><span>Reviewed locally</span></div><p>Browser-local workspace<br>No EPR submissions</p></div><div class="document-queue-toolbar"><div class="segmented" aria-label="Filter document status">${[['all','All'],['draft','Drafts'],['signed','Reviewed']].map(([id,label])=>`<button aria-pressed="${documentFilter===id}" onclick="documentFilter='${id}';render()">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input aria-label="Search documents by patient or type" value="${esc(documentQuery)}" oninput="updateDocumentSearch(this.value)" placeholder="Search patient, ID or document type"></label></div><div class="document-queue-filters"><label>Patient<select class="field" onchange="documentPatient=this.value;render()">${taskOptions([['all','All patients'],...demoPatients.map(p=>[p.id,p.name])],documentPatient)}</select></label><label>Document type<select class="field" onchange="documentTemplate=this.value;render()">${taskOptions([['all','All types'],...Object.entries(documentTemplates)],documentTemplate)}</select></label><button class="text-btn" onclick="resetDocumentFilters()">Clear filters</button></div><section class="panel" id="document-queue-results" aria-label="Document results" aria-live="polite">${documentQueueRows()}</section><p class="fine document-queue-footnote">Each synthetic patient has one current document. Earlier retained copies are available in that patient’s saved activity.</p>`;};
function previewWorkspaceDocument(id){const p=demoPatients.find(x=>x.id===id),r=p&&state.patientRecords[id];if(!r?.note.trim())return;modal(documentTitle(r.noteTemplate),`<div class="handover-identity"><strong>${esc(p.name)}</strong><span>${esc(id)} · Version ${r.version} · ${r.signed?'Reviewed locally':'Unsigned draft'}</span></div><pre class="review-copy document-preview-copy">${esc(r.note)}</pre><p class="fine">Preview only. No review is recorded and no document is sent.</p>`,`<button onclick="closeModal()">Close</button><button onclick="openDocumentActivity('${id}')">Saved activity</button><button class="primary" onclick="closeModal();openPatient('${id}','N')">Open editor</button>`);}
function openDocumentActivity(id){if(!demoPatients.some(p=>p.id===id))return;openPatient(id,'record');patientOverviewTab='activity';patientActivityFilter='document';render();}
function openDocumentForReview(id){if(!demoPatients.some(p=>p.id===id))return;openPatient(id,'N');if(state.note.trim()&&!state.signed)reviewNote();}
function workspaceReviewItems(){ensurePatientState();return demoPatients.flatMap(p=>{const r=state.patientRecords[p.id];return [...(r.note.trim()&&!r.signed?[{patient:p,kind:'document',title:documentTitle(r.noteTemplate),detail:'Version '+r.version+' · Compare the exact text with its source',to:'N'}]:[]),...(r.formData&&!r.formApproval?[{patient:p,kind:'form',title:'Follow-up preference form',detail:r.formData.filter(f=>f.reviewed&&f.value.trim()).length+' of '+r.formData.length+' fields checked',to:'F'}]:[])];});}
function filteredReviewItems(){const q=reviewQuery.trim().toLowerCase();return workspaceReviewItems().filter(i=>(reviewPatient==='all'||i.patient.id===reviewPatient)&&(reviewKind==='all'||i.kind===reviewKind)&&(!q||[i.patient.name,i.patient.id,i.title].join(' ').toLowerCase().includes(q)));}
function resetReviewFilters(){reviewQuery='';reviewPatient='all';reviewKind='all';render();}
function updateReviewSearch(value){reviewQuery=value;document.getElementById('review-queue-results').innerHTML=reviewQueueRows();}
function reviewQueueRows(){const rows=filteredReviewItems();return `<div class="panel-head"><h2>${rows.length} ${rows.length===1?'item':'items'} shown</h2><span class="fine">Individual review required</span></div>${rows.length?rows.map(i=>`<article class="review-queue-item"><span class="document-symbol">${icon(i.kind==='form'?'form':'file')}</span><div><span class="review-kind">${i.kind==='form'?'FORM':'DOCUMENT'}</span><h3>${esc(i.title)}</h3><p><strong>${esc(i.patient.name)}</strong> · ${esc(i.patient.id)}</p><small>${esc(i.detail)}</small></div><button class="primary" onclick="${i.kind==='form'?`openPatient('${i.patient.id}','F')`:`openDocumentForReview('${i.patient.id}')`}">Review ${icon('arrow')}</button></article>`).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('check')}</span><h3>${workspaceReviewItems().length?'No items match these filters':'Nothing is waiting for review'}</h3><p>${workspaceReviewItems().length?'Adjust the patient, item type or search term.':'Unsigned documents and unapproved forms appear here as you work.'}</p><button onclick="${workspaceReviewItems().length?'resetReviewFilters()':"nav('documents')"}">${workspaceReviewItems().length?'Clear filters':'Open documents'}</button></div>`}`;}
reviewPage=function(){const all=workspaceReviewItems();return pageHeading('Review queue','Check each document and form against its source before recording approval.')+`<div class="review-summary"><span class="review-number">${all.length}</span><div><h2>${all.length===1?'item needs':'items need'} review</h2><p>${all.filter(i=>i.kind==='document').length} documents · ${all.filter(i=>i.kind==='form').length} forms · All synthetic patients</p></div><span class="pill grey">Not submitted to an EPR</span></div><div class="document-queue-toolbar"><div class="segmented" aria-label="Filter review item type">${[['all','All items'],['document','Documents'],['form','Forms']].map(([id,label])=>`<button aria-pressed="${reviewKind===id}" onclick="reviewKind='${id}';render()">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input aria-label="Search review queue" value="${esc(reviewQuery)}" oninput="updateReviewSearch(this.value)" placeholder="Search patient, ID or document type"></label></div><div class="document-queue-filters"><label>Patient<select class="field" onchange="reviewPatient=this.value;render()">${taskOptions([['all','All patients'],...demoPatients.map(p=>[p.id,p.name])],reviewPatient)}</select></label><button class="text-btn" onclick="resetReviewFilters()">Clear filters</button></div><section class="panel" id="review-queue-results" aria-label="Review results" aria-live="polite">${reviewQueueRows()}</section>`;};
const documentPriorReview=reviewNote;
reviewNote=function(){if(!state.note.trim()||state.signed)return documentPriorReview();documentPriorReview();const p=currentPatient(),snapshot=pendingReview;if(!snapshot||snapshot.patientId!==p.id)return;modal('Review document · Version '+snapshot.version,`<div class="document-review-identity"><span class="avatar">${esc(p.initials)}</span><div><strong>${esc(p.name)}</strong><span>${esc(p.id)} · ${esc(documentTitle(state.noteTemplate))}</span></div><span class="pill amber">Unsigned draft</span></div><div class="document-review-grid"><section><div class="review-column-heading"><h3>Exact document for review</h3><span>Version ${snapshot.version}</span></div><pre class="review-copy">${esc(snapshot.text)}</pre></section><section><div class="review-column-heading"><h3>Source conversation</h3><span>Scripted example</span></div>${transcriptMarkup()}</section></div><p class="document-review-guidance">Check factual accuracy, omissions and any changes against the source. This screen does not automatically verify clinical accuracy.</p><label class="consent document-review-confirm"><input type="checkbox" id="review-confirm"><span>I have reviewed this exact document against its source, including omissions and edits.</span></label><p class="fine">Records a local development review only. No clinical signature, delivery or EPR submission is created.</p>`,`<button onclick="pendingReview=null;closeModal()">Back to draft</button><button class="primary" onclick="signNote()">Record local review</button>`);};
function documentReplacementSnapshot(type){return {patientId:state.selectedPatientId,text:state.note,version:state.version,revision:state.revision,previousTemplate:state.noteTemplate,type};}
function requestDocumentTemplate(type){if(!Object.hasOwn(documentTemplates,type)||state.signed||type===state.noteTemplate)return;if(!state.note.trim()){state.noteTemplate=type;pendingReview=null;save();render();return;}render();requestDocumentReplacement(type);}
function requestDocumentExample(){if(state.signed)return toast('Create an amendment before replacing a reviewed document.');if(!state.settings.ai)return toast('Enable example drafting in workspace settings first.');const type=Object.hasOwn(documentTemplates,state.noteTemplate)?state.noteTemplate:'soap';if(state.note.trim())return requestDocumentReplacement(type);applyDocumentExample(type);}
function requestDocumentReplacement(type){if(state.signed||!Object.hasOwn(documentTemplates,type))return;if(!state.settings.ai)return toast('Enable example drafting before loading a scripted template.');pendingDocumentReplacement=documentReplacementSnapshot(type);modal('Keep a copy before replacing this draft?',`<div class="handover-identity"><strong>${esc(currentPatient().name)}</strong><span>${esc(state.selectedPatientId)} · Current version ${state.version}</span></div><p>This will preserve the current text in saved activity, then load the scripted <strong>${esc(documentTitle(type))}</strong> example.</p><p>Your edits will not be carried into the example. The new text will need a fresh review.</p><details class="task-source"><summary>Current draft to preserve</summary><pre class="review-copy">${esc(state.note)}</pre></details><p class="fine">This is a predefined example, not AI rewriting or format conversion.</p>`,`<button onclick="cancelDocumentReplacement()">Keep current draft</button><button class="primary" onclick="confirmDocumentReplacement()">Save copy & load example</button>`);}
function cancelDocumentReplacement(){pendingDocumentReplacement=null;closeModal();render();}
function applyDocumentExample(type){state.noteTemplate=type;updateNote(noteForPatient(type));audit(state.selectedPatientId+': scripted '+documentTitle(type)+' loaded for review.');render();}
function confirmDocumentReplacement(){const p=pendingDocumentReplacement;if(!p||p.patientId!==state.selectedPatientId||p.text!==state.note||p.version!==state.version||p.revision!==state.revision||p.previousTemplate!==state.noteTemplate||state.signed||!state.settings.ai){pendingDocumentReplacement=null;closeModal();render();return toast('The document or setting changed. Open a fresh replacement request.');}state.history.unshift({patientId:p.patientId,version:p.version,text:p.text,status:'Draft saved before template/example replacement',at:new Date().toISOString()});pendingDocumentReplacement=null;closeModal();applyDocumentExample(p.type);toast('Previous draft retained in saved activity.');}
const documentPriorEditor=uiWorkflowFunctions.N;
uiWorkflowFunctions.N=function(){return documentPriorEditor().replace('onchange="changeTemplate(this.value)"','onchange="requestDocumentTemplate(this.value)"').replace('onclick="draftNote()"','onclick="requestDocumentExample()"').replace('Save draft version</button>','Save draft copy</button>').replace('Review & sign</button>','Review document</button>');};
const documentPriorPatientSelect=selectPatient;
selectPatient=function(id){if(!demoPatients.some(p=>p.id===id))return;pendingDocumentReplacement=null;return documentPriorPatientSelect(id);};
render();
